package httpserver

import (
	"encoding/csv"
	"encoding/json"
	"net/http"
	"net/http/httptest"
	"net/url"
	"os"
	"strings"
	"testing"
	"time"

	"tascop11/engine/internal/kb"
	"tascop11/engine/internal/model"
)

// Eval per PLAN.md §11. Runs against the real 30-POI kb.json when present
// (generated by preprocess/build_kb.py + cmd/enrich); skips gracefully
// otherwise since build/ is gitignored. Paths are relative to this package
// dir (engine/internal/httpserver/), three levels below engine/.

func loadEvalServer(t *testing.T) (*Server, *kb.KB) {
	t.Helper()
	kbDir := "../../build"
	if _, err := os.Stat(kbDir + "/kb.json"); err != nil {
		t.Skip("build/kb.json not found — run preprocess/build_kb.py (+ cmd/enrich) first")
	}
	real, err := kb.LoadKB(kbDir, false) // eval mode: exclude UGC
	if err != nil {
		t.Fatalf("LoadKB: %v", err)
	}
	return &Server{kb: real, hcmLoc: time.UTC}, real
}

type evalRow struct {
	Category      string
	UserQuery     string
	ExpectedFocus string
	TaskType      string
	Difficulty    string
}

func loadPublicEval(t *testing.T) []evalRow {
	t.Helper()
	paths := []string{
		"../../../data/ai_maps_track6_dataset_participants.xlsm - Public Evaluation.csv",
		"../../../preprocess/data/ai_maps_track6_dataset_participants.xlsm - Public Evaluation.csv",
	}
	var f *os.File
	var err error
	for _, p := range paths {
		f, err = os.Open(p)
		if err == nil {
			break
		}
	}
	if f == nil {
		t.Skipf("Public Evaluation CSV not found in %v", paths)
	}
	defer f.Close()

	r := csv.NewReader(f)
	records, err := r.ReadAll()
	if err != nil {
		t.Fatalf("read Public Evaluation CSV: %v", err)
	}
	if len(records) < 2 {
		t.Fatalf("Public Evaluation CSV has no data rows")
	}
	var rows []evalRow
	for _, rec := range records[1:] { // skip header
		if len(rec) < 5 {
			continue
		}
		rows = append(rows, evalRow{
			Category:      rec[0],
			UserQuery:     rec[1],
			ExpectedFocus: rec[2],
			TaskType:      rec[3],
			Difficulty:    rec[4],
		})
	}
	return rows
}

func (s *Server) doRecommend(t *testing.T, q url.Values) model.RecommendResponse {
	t.Helper()
	req := httptest.NewRequest(http.MethodGet, "/v1/recommend?"+q.Encode(), nil)
	rec := httptest.NewRecorder()
	s.handleRecommend(rec, req)
	if rec.Code != http.StatusOK {
		t.Fatalf("recommend(%s) status = %d, want 200; body=%s", q.Encode(), rec.Code, rec.Body.String())
	}
	var resp model.RecommendResponse
	if err := json.Unmarshal(rec.Body.Bytes(), &resp); err != nil {
		// Body may be a NotFound instead of RecommendResponse — caller checks raw JSON separately.
		return model.RecommendResponse{}
	}
	return resp
}

func (s *Server) doRecommendRaw(t *testing.T, q url.Values) map[string]any {
	t.Helper()
	req := httptest.NewRequest(http.MethodGet, "/v1/recommend?"+q.Encode(), nil)
	rec := httptest.NewRecorder()
	s.handleRecommend(rec, req)
	if rec.Code != http.StatusOK {
		t.Fatalf("recommend(%s) status = %d, want 200; body=%s", q.Encode(), rec.Code, rec.Body.String())
	}
	var body map[string]any
	if err := json.Unmarshal(rec.Body.Bytes(), &body); err != nil {
		t.Fatalf("recommend(%s) body not JSON: %v", q.Encode(), err)
	}
	return body
}

// --- Group A: 15 Public Evaluation questions, sanity + anti-hallucination ---

func TestEvalGroupA_PublicEval(t *testing.T) {
	s, _ := loadEvalServer(t)
	rows := loadPublicEval(t)

	pass, fail := 0, 0
	for _, row := range rows {
		body := s.doRecommendRaw(t, url.Values{"q": {row.UserQuery}, "eval": {"1"}})

		switch row.Category {
		case "Review Analysis": // Crystal BBQ trap
			if body["status"] == "not_found" && strings.Contains(row.UserQuery, "Crystal BBQ") {
				pass++
			} else {
				fail++
				t.Errorf("[%s] %q: want honest not_found (Crystal BBQ absent from KB), got %v", row.Category, row.UserQuery, body)
			}
		case "Halal": // Halal-HCM honesty trap
			if body["status"] == "not_found" {
				pass++
			} else {
				fail++
				t.Errorf("[%s] %q: want honest not_found (no Halal in dataset), got %v", row.Category, row.UserQuery, body)
			}
		default:
			// Sanity only: must respond 200 (already guaranteed by doRecommendRaw)
			// without crashing or erroring; not a hallucination trap.
			pass++
		}
	}
	t.Logf("Group A (Public Evaluation): %d/%d pass, %d fail", pass, len(rows), fail)
}

// --- Group B: 5 personalization questions (PLAN.md §11 prose) ---

func TestEvalGroupB_Personalize(t *testing.T) {
	s, real := loadEvalServer(t)

	pass, total := 0, 5

	// B1: segment=romantic -> fastfood-tagged POIs are outranked (segments are
	// a SOFT persona factor in rerank.go, not a HARD gate, so this checks the
	// top-3 rather than demanding zero fastfood results anywhere in the list).
	t.Run("romantic_excludes_fastfood", func(t *testing.T) {
		q := url.Values{"segment": {"romantic"}}
		resp := s.doRecommend(t, q)
		limit := 3
		if len(resp.Results) < limit {
			limit = len(resp.Results)
		}
		ok := limit > 0
		for i := 0; i < limit; i++ {
			if kb.ContainsStr(resp.Results[i].Tags, "fastfood") {
				ok = false
			}
		}
		if ok {
			pass++
		} else {
			t.Errorf("romantic segment top-3 includes a fastfood-tagged result")
		}
	})

	// B2: diet=vegetarian -> every result POI has vegetarian evidence.
	t.Run("vegetarian_diet", func(t *testing.T) {
		q := url.Values{"diet": {"vegetarian"}}
		resp := s.doRecommend(t, q)
		ok := len(resp.Results) > 0
		for _, r := range resp.Results {
			p := real.Get(r.ID)
			if p == nil || !kb.DietMatch(p, "vegetarian") {
				ok = false
			}
		}
		if ok {
			pass++
		} else {
			t.Errorf("vegetarian diet filter let a non-vegetarian POI through (or returned nothing)")
		}
	})

	// B3: time=00:30 -> every result POI is open at that minute.
	t.Run("late_night_open", func(t *testing.T) {
		q := url.Values{"time": {"00:30"}}
		resp := s.doRecommend(t, q)
		ok := len(resp.Results) > 0
		for _, r := range resp.Results {
			p := real.Get(r.ID)
			if p == nil || !kb.IsOpenAt(p.Opening, 30) {
				ok = false
			}
		}
		if ok {
			pass++
		} else {
			t.Errorf("time=00:30 filter let a closed POI through (or returned nothing)")
		}
	})

	// B4: segment=family -> top result has parking or kid_friendly.
	t.Run("family_amenities", func(t *testing.T) {
		q := url.Values{"segment": {"family"}}
		resp := s.doRecommend(t, q)
		ok := false
		if len(resp.Results) > 0 {
			p := real.Get(resp.Results[0].ID)
			if p != nil && (kb.ContainsStr(p.Amenities, "parking") || kb.ContainsStr(p.Amenities, "kid_friendly")) {
				ok = true
			}
		}
		if ok {
			pass++
		} else {
			t.Errorf("family segment top result missing parking/kid_friendly amenity")
		}
	})

	// B5: price=budget -> no result POI is premium.
	t.Run("budget_excludes_premium", func(t *testing.T) {
		q := url.Values{"price": {"budget"}}
		resp := s.doRecommend(t, q)
		ok := len(resp.Results) > 0
		for _, r := range resp.Results {
			p := real.Get(r.ID)
			if p == nil || p.PriceLevel == "premium" {
				ok = false
			}
		}
		if ok {
			pass++
		} else {
			t.Errorf("price=budget filter let a premium POI through (or returned nothing)")
		}
	})

	t.Logf("Group B (Personalize): %d/%d pass", pass, total)
}

// --- Group C: 3 localization questions (PLAN.md §11 prose) ---

func TestEvalGroupC_Localize(t *testing.T) {
	s, real := loadEvalServer(t)

	pass, total := 0, 3

	hanoiLat, hanoiLon := "21.0285", "105.8542"
	hcmLat, hcmLon := "10.7769", "106.7009"

	// C1: HN coords -> nearest (top) result is in Hà Nội, and Hà Nội results
	// are not mixed with TP.HCM ones in the top-3 (geo_decay is a SOFT factor
	// alongside quality/rating, so it narrows toward the user's city without a
	// HARD city partition — this checks that narrowing, and specifically the
	// "không lẫn HCM" honesty-trap wording from PLAN.md §11).
	t.Run("hanoi_top3_in_hanoi", func(t *testing.T) {
		resp := s.doRecommend(t, url.Values{"lat": {hanoiLat}, "lon": {hanoiLon}})
		ok := len(resp.Results) >= 1
		if ok {
			top := real.Get(resp.Results[0].ID)
			if top == nil || !strings.Contains(top.City, "Hà Nội") {
				ok = false
			}
		}
		limit := 3
		if len(resp.Results) < limit {
			limit = len(resp.Results)
		}
		for i := 0; i < limit; i++ {
			p := real.Get(resp.Results[i].ID)
			if p != nil && strings.Contains(p.City, "Hồ Chí Minh") {
				ok = false
			}
		}
		if ok {
			pass++
		} else {
			t.Errorf("nearby results from Hà Nội coords: top result not in Hà Nội, or top-3 mixed with TP.HCM")
		}
	})

	// C2: changing location changes the top result.
	t.Run("location_changes_top_result", func(t *testing.T) {
		hn := s.doRecommend(t, url.Values{"lat": {hanoiLat}, "lon": {hanoiLon}})
		hcm := s.doRecommend(t, url.Values{"lat": {hcmLat}, "lon": {hcmLon}})
		if len(hn.Results) > 0 && len(hcm.Results) > 0 && hn.Results[0].ID != hcm.Results[0].ID {
			pass++
		} else {
			t.Errorf("top result did not change between Hà Nội and TP.HCM coordinates")
		}
	})

	// C3: explicit city in query overrides user location.
	t.Run("query_city_overrides_location", func(t *testing.T) {
		resp := s.doRecommend(t, url.Values{"q": {"bún chả HCM"}, "lat": {hanoiLat}, "lon": {hanoiLon}})
		ok := false
		if len(resp.Results) > 0 {
			p := real.Get(resp.Results[0].ID)
			if p != nil && strings.Contains(p.City, "Hồ Chí Minh") {
				ok = true
			}
		}
		if ok {
			pass++
		} else {
			t.Errorf("query naming TP.HCM did not override Hà Nội user location")
		}
	})

	t.Logf("Group C (Localize): %d/%d pass", pass, total)
}
